// File: tools/zshader/Emit.cpp
//
// The two files the tool writes, as text. The generated files are a contract --
// the engine compiles them, and the build only rewrites them when their content
// changes -- so the text that does not vary is written here the way the files
// read, and only what the catalog decides is formatted in. Nothing here reflects
// anything or parses an argument: it takes the model and returns the bytes.
//
// Four ways to add text, one per shape the emitter needs: Line for a formatted
// line, Verbatim for a line whose text is already final (the generated C++'s own
// punctuation, which std::format would read as replacement fields), Raw for a
// run of already-final text with the newlines written into it, and Blank for the
// empty lines that separate the generated blocks. None of them is called with a
// bare string meant to be formatted: a call with one argument is always text.

#include "ZShader.hpp"

#include <format>
#include <iterator>
#include <string>
#include <string_view>
#include <vector>

namespace ZHLN::ZShader {

namespace {

// The indent a binding list's entries sit at: the list is emitted inside a
// class body, four spaces past the line that opens it.
constexpr std::string_view kSlotIndent = "        ";

// One generated file, appended to a piece at a time. Everything the tool
// writes goes through here, so no call site has to remember where a line ends.
class Writer {
  public:
    explicit Writer(std::string& sink) noexcept: _out(sink) {
    }

    Writer(const Writer&)            = delete;
    Writer& operator=(const Writer&) = delete;

    // One line, formatted.
    template <typename... Args>
    void Line(std::format_string<Args...> fmt, Args&&... args) {
        Fragment(fmt, std::forward<Args>(args)...);
        Blank();
    }

    // A piece of a line: for the half a helper builds, like a binding list the
    // caller wraps in `using ... = ...;` on a line of its own.
    template <typename... Args>
    void Fragment(std::format_string<Args...> fmt, Args&&... args) {
        std::format_to(std::back_inserter(_out), fmt, std::forward<Args>(args)...);
    }

    // One line as it stands.
    void Verbatim(std::string_view text) {
        Raw(text);
        Blank();
    }

    // A run of text exactly as written, newlines and all.
    void Raw(std::string_view text) {
        _out.append(text);
    }

    // The empty line the generated files separate their blocks with.
    void Blank() {
        _out.push_back('\n');
    }

  private:
    std::string& _out;
};

// One module's binding list: the declarations the write side holds itself
// against, in the order the module declares them (set and binding ascending,
// which ReflectModule sorted). A module that declares none gets an empty list
// rather than a list with no entries.
auto BindingList(std::span<const Descriptor> descriptors, bool sampler, std::string_view indent) -> std::string {
    if (descriptors.empty()) {
        return "Vk::BindingList<>";
    }
    std::string text;
    Writer      out(text);
    out.Verbatim("Vk::BindingList<");
    for (size_t index = 0; index < descriptors.size(); ++index) {
        const Descriptor& descriptor = descriptors[index];
        const std::string entry      = sampler
                                           ? std::format("Vk::Declared::SamplerSlot<\"{}\", {}, {}>", descriptor.name, descriptor.set, descriptor.binding)
                                           : std::format("Vk::Declared::ResourceSlot<\"{}\", {}, {}, {}>", descriptor.name, descriptor.type, descriptor.set, descriptor.binding);
        out.Line("{}    {}{}", indent, entry, index + 1 == descriptors.size() ? "" : ",");
    }
    out.Fragment("{}>", indent);
    return text;
}

// One set's members: the modules whose bindings that descriptor block serves.
auto ModuleList(std::span<const std::string> types) -> std::string {
    std::string text;
    Writer      out(text);
    for (size_t index = 0; index < types.size(); ++index) {
        out.Fragment("{}{}", index == 0 ? "Modules::" : ", Modules::", types[index]);
    }
    return text;
}

// ShaderBindings.hpp up to the byte spans, which are one per input.
constexpr std::string_view kHeaderPreamble = R"ZHLN(// Copyright (C) 2026 Evilpasture | evilpasture+github@proton.me
// SPDX-License-Identifier: GPL-3.0-or-later

// File: <build>/generated_shaders/ShaderBindings.hpp
//
// GENERATED by tools/zshader from Slang's reflection of each module's
// source, kept to the entry point's usage table. Do not edit.
//
// One type per module: its entry point, its stage, the bindings it declares with
// their descriptor types and numbers, and the push-constant members its
// declared blocks carry.
// One `Vk::ShaderSet<...>` alias per pass, which is what a descriptor write names.
// No bytes: the modules themselves live in the generated ShaderBytecode.cpp, and
// these lists are the only description of them.

#pragma once

#include "Rendering.hpp" // the RHI implementation headers
#include "pipeline/ShaderProgram.hpp" // Vk::ShaderProgram, Vk::ShaderSet
#include "pipeline/SpirvLayout.hpp" // Vk::WorkgroupSize (the compute LocalSize below)

#include <cstdint>
#include <span>
#include <string_view>

namespace ZHLN::ShaderLib {

// One cooked module's bytes, defined in the generated ShaderBytecode.cpp --
// the only translation unit in the project that #embeds them. Defined once,
// so the image holds one copy of each module however many sites read it.
)ZHLN";

// ShaderBindings.hpp from the end of the byte spans to the first module type.
constexpr std::string_view kHeaderModulesOpen = R"ZHLN(
} // namespace ZHLN::ShaderLib

namespace ZHLN::Shaders {

// The modules themselves. A set named after a pass (Lighting) is a different
// declaration from the module it wraps, which is why the two live in separate
// namespaces.
namespace Modules {
)ZHLN";

// The entry point and stage of one module: the two things a pipeline is built
// with, both read out of the module.
constexpr std::string_view kHeaderEntryPoint = R"ZHLN(
    // The entry point the module declares, and the stage it was compiled
    // for: what a pipeline is built with, read out of the module.
)ZHLN";

// Where the module lives, for a hot reload and for a reader that wants to
// compare the catalog against the file itself.
constexpr std::string_view kHeaderSource = R"ZHLN(
    // The cooked module these declarations came from, for a hot reload and
    // for a reader that wants to compare against the file itself.
)ZHLN";

// The push-constant view, when the module declares any block.
constexpr std::string_view kHeaderPushOpen = R"ZHLN(
    // The push-constant members the module's declared blocks carry, at
    // block-relative offsets, and how far they reach. Slang's usage table
    // stops before the push category, so every DECLARED block contributes and
    // the emitted module may carry fewer. The engine reads presence from here
    // (Vk::DeclaresPushBlock) and nothing else: the struct a pass pushes is
    // the generated one, so there is no second layout to compare against.
)ZHLN";

// ShaderBindings.hpp from the end of the module types to the first set alias.
constexpr std::string_view kHeaderSetsOpen = R"ZHLN(
} // namespace Modules

// One set per descriptor block: the modules whose bindings that block
// serves. A write site names the set, and the set is what the compile-time
// checks read.
)ZHLN";

// ShaderBindings.hpp's last line.
constexpr std::string_view kHeaderClose = R"ZHLN(
} // namespace ZHLN::Shaders
)ZHLN";

// ShaderBytecode.cpp up to the embedded modules.
constexpr std::string_view kSourcePreamble = R"ZHLN(// Copyright (C) 2026 Evilpasture | evilpasture+github@proton.me
// SPDX-License-Identifier: GPL-3.0-or-later

// File: <build>/generated_shaders/ShaderBytecode.cpp
//
// GENERATED by tools/zshader. Do not edit.
//
// The translation unit that #embeds every cooked module the catalog carries and
// defines each module's Bytes(). It is bytes and accessors, nothing else: the
// header beside it describes those modules from Slang's reflection, and the
// cooked bytes are never decoded to second-guess that description.

#include "ShaderBindings.hpp"

#include <cstdint>
#include <span>

namespace {

)ZHLN";

// Clang diagnoses #embed as a C23 extension while compiling the generated C++ TU.
constexpr std::string_view kSourceEmbedPragmaOpen = R"ZHLN(#if defined(__clang__)
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wc23-extensions"
#endif

)ZHLN";

constexpr std::string_view kSourceEmbedPragmaClose = R"ZHLN(
#if defined(__clang__)
#pragma clang diagnostic pop
#endif

)ZHLN";

// ShaderBytecode.cpp from the end of the embedded arrays to the span
// definitions they are read through.
constexpr std::string_view kSourceSpansOpen = R"ZHLN(} // namespace

namespace ZHLN::ShaderLib {

)ZHLN";

// ShaderBytecode.cpp from the end of the span definitions to the Bytes()
// definitions.
constexpr std::string_view kSourceBytesOpen = R"ZHLN(
} // namespace ZHLN::ShaderLib

namespace ZHLN::Shaders::Modules {

)ZHLN";

// ShaderBytecode.cpp's last line.
constexpr std::string_view kSourceClose = R"ZHLN(} // namespace ZHLN::Shaders::Modules
)ZHLN";

} // namespace

auto EmitHeader(const Options& options) -> std::string {
    std::string text;
    Writer      out(text);

    out.Raw(kHeaderPreamble);
    for (const BytesInput& input: BytesInputsOf(options)) {
        out.Line("extern const std::span<const uint8_t> {}; // {}", input.symbol, input.path);
    }
    out.Raw(kHeaderModulesOpen);

    for (const auto& [type, macro]: options.catalog) {
        const Module& module = ModuleFor(options, type, macro);

        out.Blank();
        out.Line("struct {} {{", type);
        out.Line("    using Resources = {};", BindingList(module.resources, false, kSlotIndent));
        out.Line("    using Samplers  = {};", BindingList(module.samplers, true, kSlotIndent));
        out.Raw(kHeaderEntryPoint);
        out.Line("    static constexpr const char*           EntryPoint = \"{}\";", module.entryPoint);
        out.Line("    static constexpr VkShaderStageFlagBits Stage      = {};", module.stage);
        out.Raw(kHeaderSource);
        out.Line("    static constexpr const char* Path = \"{}\";", AsLiteral(module.path));
        if (module.stage == "VK_SHADER_STAGE_COMPUTE_BIT") {
            // The threadgroup size the entry point declares: Slang's own
            // reflection of [numthreads] (SlangReflect.cpp), which is the only
            // place the number is read. Dispatch math keys off it at compile
            // time through Vk::LocalSizeOf.
            out.Line(
                "    static constexpr Vk::WorkgroupSize LocalSize = {{{}, {}, {}}};", module.localSize[0], module.localSize[1], module.localSize[2]
            );
        }

        if (!module.pushes.empty()) {
            // The catalog's push view is the union of every block the module
            // declares: Slang cannot say which blocks survive to emission
            // (its usage table stops before the push category -- see
            // SlangReflect.hpp), so the declarations are what the generator
            // has. Member offsets are block-relative, exactly as the cooked
            // bytes carry them; the size is the furthest any declared block
            // reaches. The engine reads this list to know *that* the module
            // takes a push payload (Vk::DeclaresPushBlock), never to compare
            // it against a struct: the struct a pass pushes is generated from
            // the same Slang declaration.
            uint32_t pushSize = 0;
            for (const PushBlock& block: module.pushes) {
                pushSize = pushSize > block.paddedSize ? pushSize : block.paddedSize;
            }
            out.Raw(kHeaderPushOpen);
            out.Line("    static constexpr uint32_t   PushSize = {};", pushSize);
            out.Verbatim("    static constexpr Vk::PushMember Push[] = {");
            for (const PushBlock& block: module.pushes) {
                for (const PushMember& member: block.members) {
                    out.Line("        {{\"{}\", {}, {}}},", member.name, member.offset, member.size);
                }
            }
            out.Verbatim("    };");
        }

        out.Blank();
        out.Verbatim("    [[nodiscard]] static auto Bytes() -> std::span<const uint8_t>;");
        out.Verbatim("};");
    }

    out.Raw(kHeaderSetsOpen);
    for (const auto& [name, members]: options.sets) {
        out.Line("using {} = Vk::ShaderSet<{}>;", name, ModuleList(members));
    }
    out.Raw(kHeaderClose);
    return text;
}

auto EmitSource(const Options& options) -> std::string {
    std::string text;
    Writer      out(text);

    out.Raw(kSourcePreamble);
    out.Raw(kSourceEmbedPragmaOpen);
    for (const BytesInput& input: BytesInputsOf(options)) {
        // A descriptor's C ABI exposes these bytes as uint32_t SPIR-V words.
        out.Line("alignas(uint32_t) constexpr uint8_t {}_bytes[] = {{", input.symbol);
        out.Line("#embed \"{}\"", AsLiteral(input.path));
        out.Verbatim("};");
        if (input.hasExpectedSize) {
            out.Line("static_assert(sizeof({}_bytes) == {});", input.symbol, input.size);
        } else {
            out.Line("static_assert(sizeof({0}_bytes) > 0 && (sizeof({0}_bytes) % sizeof(uint32_t)) == 0);", input.symbol);
        }
        out.Blank();
    }

    out.Raw(kSourceEmbedPragmaClose);
    out.Raw(kSourceSpansOpen);
    for (const BytesInput& input: BytesInputsOf(options)) {
        out.Line("const std::span<const uint8_t> {0} {{{0}_bytes}};", input.symbol);
    }

    out.Raw(kSourceBytesOpen);
    for (const auto& [type, macro]: options.catalog) {
        const Module& module = ModuleFor(options, type, macro);
        out.Line("auto {}::Bytes() -> std::span<const uint8_t> {{", type);
        out.Line("    return ZHLN::ShaderLib::{};", module.symbol);
        out.Verbatim("}");
        out.Blank();
    }

    out.Raw(kSourceClose);
    return text;
}

} // namespace ZHLN::ZShader
